@push('scripts')<script>$(function(){const modal=new bootstrap.Modal('#modalForm'),table=$('#table').DataTable({processing:true,serverSide:true,ajax:'{{ route('kelas.index') }}',columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'nama_kelas'},{data:'tingkat'},{data:'jenis'},{data:'status'},{data:'jumlah_siswa',orderable:false,searchable:false},{data:'action',orderable:false,searchable:false}]});function reset(){$('#formData')[0].reset();$('#kelas_id').val('');$('#errors').addClass('d-none');$('.modal-title').text('Tambah Kelas')}$('#btn-add').click(()=>{reset();modal.show()});$(document).on('click','.btn-edit',function(){reset();const id=$(this).data('id');$.get('{{ route('kelas.show',':id') }}'.replace(':id',id),r=>{Object.entries(r.data).forEach(([k,v])=>$('[name="'+k+'"]').val(v));$('#kelas_id').val(id);$('.modal-title').text('Edit Kelas');modal.show()})});$('#formData').submit(function(e){e.preventDefault();const id=$('#kelas_id').val(),data=$(this).serializeArray();if(id)data.push({name:'_method',value:'PUT'});$.ajax({url:id?'{{ route('kelas.update',':id') }}'.replace(':id',id):'{{ route('kelas.store') }}',type:'POST',data,success:r=>{modal.hide();table.ajax.reload();toastr.success(r.message)},error:x=>$('#errors').removeClass('d-none').html(Object.values(x.responseJSON.errors||{}).flat().join('<br>'))})});$(document).on('click','.btn-delete',function(){const id=$(this).data('id');Swal.fire({title:'Hapus kelas?',icon:'warning',showCancelButton:true}).then(r=>{if(r.isConfirmed)$.ajax({url:'{{ route('kelas.destroy',':id') }}'.replace(':id',id),type:'DELETE',data:{_token:'{{ csrf_token() }}'},success:x=>{table.ajax.reload();toastr.success(x.message)}})})})});</script>@endpush
